1	import { useAuth } from "@/hooks/useAuth";
2	import { supabase } from "@/integrations/supabase/client";
3	import SidebarLayout from "@/components/SidebarLayout";
4	import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
5	import { Button } from "@/components/ui/button";
6	import { Switch } from "@/components/ui/switch";
7	import { LogOut, Zap } from "lucide-react";
8	import { toast } from "sonner";
9	import ChangePasswordCard from "@/components/settings/ChangePasswordCard";
10	import { FadeIn } from "@/components/ui/fade-in";
11	import { StaggerList } from "@/components/ui/stagger-list";
12	
13	const Settings = () => {
14	  const { user, profile, signOut, refreshProfile } = useAuth();
15	  const autoRank = profile?.auto_rank_enabled ?? true;
16	
17	  const toggleAutoRank = async (enabled: boolean) => {
18	    if (!user) return;
19	    try {
20	      const { error } = await supabase
21	        .from("profiles")
22	        .update({ auto_rank_enabled: enabled } as any)
23	        .eq("user_id", user.id);
24	      if (error) throw error;
25	      await refreshProfile();
26	      toast.success(enabled ? "Auto-rank enabled" : "Auto-rank disabled");
27	    } catch {
28	      toast.error("Failed to update setting");
29	    }
30	  };
31	
32	  return (
33	    <SidebarLayout>
34	      <main className="w-full max-w-[700px] mx-auto px-4 sm:px-6 lg:px-8 py-8">
35	        <FadeIn>
36	          <h1 className="text-xl font-semibold text-foreground tracking-tight mb-6">Settings</h1>
37	        </FadeIn>
38	        <StaggerList className="space-y-6" stagger={0.08}>
39	          {/* Auto-rank toggle */}
40	          <Card>
41	            <CardHeader className="pb-3">
42	              <div className="flex items-center justify-between">
43	                <div className="flex items-center gap-2">
44	                  <Zap className="h-5 w-5 text-primary" />
45	                  <CardTitle className="text-lg">Auto-rank resumes</CardTitle>
46	                </div>
47	                <Switch checked={autoRank} onCheckedChange={toggleAutoRank} />
48	              </div>
49	              <CardDescription>
50	                {autoRank
51	                  ? "Resumes are automatically scored after upload. Credits are used immediately."
52	                  : "Resumes stay as Pending after upload. You choose when to rank and spend credits."}
53	              </CardDescription>
54	            </CardHeader>
55	          </Card>
56	
57	          <ChangePasswordCard />
58	
59	          <Card>
60	            <CardHeader>
61	              <CardTitle className="flex items-center gap-2 text-lg">
62	                <LogOut className="h-5 w-5" />
63	                Account
64	              </CardTitle>
65	            </CardHeader>
66	            <CardContent>
67	              <Button variant="outline" onClick={signOut}>
68	                Sign out
69	              </Button>
70	            </CardContent>
71	          </Card>
72	        </StaggerList>
73	      </main>
74	    </SidebarLayout>
75	  );
76	};
77	
78	export default Settings;
79	
