1	import { useState } from "react";
2	import AppHeader from "@/components/AppHeader";
3	import AdminSidebar, { type AdminSection } from "@/components/admin/AdminSidebar";
4	import AdminErrorBoundary from "@/components/admin/AdminErrorBoundary";
5	import DashboardTab from "@/components/admin/DashboardTab";
6	import UsersTab from "@/components/admin/UsersTab";
7	import BillingTab from "@/components/admin/BillingTab";
8	import PlatformSettingsTab from "@/components/admin/PlatformSettingsTab";
9	import EmailSettingsTab from "@/components/admin/EmailSettingsTab";
10	import AIPromptsTab from "@/components/admin/AIPromptsTab";
11	import IntegrationsTab from "@/components/admin/IntegrationsTab";
12	import UsageLogsTab from "@/components/admin/UsageLogsTab";
13	import AuditLogsTab from "@/components/admin/AuditLogsTab";
14	import SystemErrorLogsTab from "@/components/admin/SystemErrorLogsTab";
15	import SeoTab from "@/components/admin/SeoTab";
16	import ChangelogTab from "@/components/admin/ChangelogTab";
17	
18	const sectionComponents: Record<AdminSection, React.ComponentType> = {
19	  dashboard: DashboardTab,
20	  users: UsersTab,
21	  billing: BillingTab,
22	  platform_settings: PlatformSettingsTab,
23	  email_settings: EmailSettingsTab,
24	  ai_prompts: AIPromptsTab,
25	  seo: SeoTab,
26	  changelog: ChangelogTab,
27	  integrations: IntegrationsTab,
28	  logs: UsageLogsTab,
29	  audit_logs: AuditLogsTab,
30	  system_errors: SystemErrorLogsTab,
31	};
32	
33	const Admin = () => {
34	  const [section, setSection] = useState<AdminSection>("dashboard");
35	  const ActiveComponent = sectionComponents[section];
36	
37	  return (
38	    <div className="h-svh flex overflow-hidden">
39	      <AdminSidebar active={section} onSelect={setSection} />
40	      <div className="flex-1 flex flex-col overflow-hidden">
41	        <AppHeader />
42	        <main className="flex-1 overflow-y-auto p-6">
43	          <AdminErrorBoundary key={section}>
44	            <ActiveComponent />
45	          </AdminErrorBoundary>
46	        </main>
47	      </div>
48	    </div>
49	  );
50	};
51	
52	export default Admin;
53	
