59	        <CardHeader className="text-center space-y-2">
60	          <div className="flex items-center justify-center gap-2 mb-2">
61	            <Zap className="h-7 w-7 text-primary" />
62	            <span className="text-xl font-bold text-foreground tracking-tight">Rankora</span>
63	          </div>
64	          <CardTitle className="text-2xl">
65	            {inviteToken ? "Join Your Team" : "Welcome"}
66	          </CardTitle>
67	          <CardDescription>
68	            {inviteToken
